// ── KOENIG GLOBE — 14 countries ──
const GLOBE_MARKERS = [
  { lat: 28.61,  lng: 77.21,   label: "India",        cc: "in" },
  { lat: 25.20,  lng: 55.27,   label: "UAE",          cc: "ae" },
  { lat: 36.19,  lng: 44.01,   label: "Iraq",         cc: "iq" },
  { lat: 24.69,  lng: 46.72,   label: "Saudi Arabia", cc: "sa" },
  { lat: 51.51,  lng: -0.13,   label: "UK",           cc: "gb" },
  { lat: 52.37,  lng: 4.90,    label: "Netherlands",  cc: "nl" },
  { lat: 53.34,  lng: -6.27,   label: "Ireland",      cc: "ie" },
  { lat: 40.71,  lng: -74.01,  label: "USA",          cc: "us" },
  { lat: 43.65,  lng: -79.38,  label: "Canada",       cc: "ca" },
  { lat: 1.35,   lng: 103.82,  label: "Singapore",    cc: "sg" },
  { lat: -33.87, lng: 151.21,  label: "Australia",    cc: "au" },
  { lat: 35.68,  lng: 139.69,  label: "Japan",        cc: "jp" },
  { lat: -26.20, lng: 28.04,   label: "South Africa", cc: "za" },
  { lat: -1.29,  lng: 36.82,   label: "Kenya",        cc: "ke" },
];

// Fixed globe orientation — centered on Eastern hemisphere (India/Middle East/Europe)
const STATIC_PHI = -0.5;
const STATIC_THETA = 0.25;

function projectMarker(lat, lng) {
  const lat_r = lat * Math.PI / 180;
  const lng_r = lng * Math.PI / 180;
  const x = Math.cos(lat_r) * Math.sin(lng_r);
  const y = Math.sin(lat_r);
  const z = Math.cos(lat_r) * Math.cos(lng_r);
  const cos_phi = Math.cos(STATIC_PHI), sin_phi = Math.sin(STATIC_PHI);
  const xr = x * cos_phi + z * sin_phi;
  const yr = y;
  const zr = -x * sin_phi + z * cos_phi;
  const cos_th = Math.cos(STATIC_THETA), sin_th = Math.sin(STATIC_THETA);
  const xf = xr;
  const yf = yr * cos_th - zr * sin_th;
  const zf = yr * sin_th + zr * cos_th;
  if (zf < 0.15) return null; // hide markers near the limb / behind globe
  const nx = (xf + 1) / 2;
  const ny = (1 - yf) / 2;
  // reject if too close to globe edge (keeps dots safely inside the circle)
  const dx = nx - 0.5, dy = ny - 0.5;
  if (Math.sqrt(dx * dx + dy * dy) > 0.42) return null;
  return { x: nx, y: ny };
}

function projectMarkerDynamic(lat, lng, phi, theta) {
  const lat_r = lat * Math.PI / 180;
  const lng_r = lng * Math.PI / 180;
  const x = Math.cos(lat_r) * Math.sin(lng_r);
  const y = Math.sin(lat_r);
  const z = Math.cos(lat_r) * Math.cos(lng_r);
  const cos_phi = Math.cos(phi), sin_phi = Math.sin(phi);
  const xr = x * cos_phi + z * sin_phi;
  const yr = y;
  const zr = -x * sin_phi + z * cos_phi;
  const cos_th = Math.cos(theta), sin_th = Math.sin(theta);
  const xf = xr;
  const yf = yr * cos_th - zr * sin_th;
  const zf = yr * sin_th + zr * cos_th;
  if (zf < 0.15) return null;
  const nx = (xf + 1) / 2;
  const ny = (1 - yf) / 2;
  const dx = nx - 0.5, dy = ny - 0.5;
  if (Math.sqrt(dx * dx + dy * dy) > 0.42) return null;
  return { x: nx, y: ny };
}

const KOENIG_GLOBE_CONFIG = {
  width: 800, height: 800,
  onRender: () => {},
  devicePixelRatio: 2,
  phi: 0.6, theta: 0.25,
  dark: 0,
  diffuse: 0.5,
  mapSamples: 18000,
  mapBrightness: 1.4,
  baseColor: [0.88, 0.93, 0.98],
  markerColor: [6/255, 148/255, 209/255],
  glowColor: [0.72, 0.88, 0.98],
  markers: GLOBE_MARKERS.map(m => ({ location: [m.lat, m.lng], size: m.label === "India" ? 0.1 : m.label === "USA" || m.label === "UK" ? 0.08 : 0.055 })),
};

function InteractiveGlobe({ size = 520 }) {
  let width = 0;
  const canvasRef = useRef(null);
  const wrapRef = useRef(null);
  const phiRef = useRef(STATIC_PHI);
  const thetaRef = useRef(STATIC_THETA);
  const dragging = useRef(false);
  const lastXRef = useRef(0);
  const lastYRef = useRef(0);
  const [isDragging, setIsDragging] = useState(false);
  const markerRefsRef = useRef<(HTMLDivElement | null)[]>([]);

  const onResize = () => {
    if (canvasRef.current) width = canvasRef.current.offsetWidth;
  };

  useEffect(() => {
    let globe = null;
    let cancelled = false;
    const canvas = canvasRef.current;

    const onPointerDown = (e) => {
      dragging.current = true;
      setIsDragging(true);
      const src = e.touches ? e.touches[0] : e;
      lastXRef.current = src.clientX;
      lastYRef.current = src.clientY;
    };
    const onPointerMove = (e) => {
      if (!dragging.current) return;
      const src = e.touches ? e.touches[0] : e;
      const dx = src.clientX - lastXRef.current;
      const dy = src.clientY - lastYRef.current;
      phiRef.current -= dx * 0.006;
      thetaRef.current = Math.max(-0.6, Math.min(0.6, thetaRef.current + dy * 0.006));
      lastXRef.current = src.clientX;
      lastYRef.current = src.clientY;
    };
    const onPointerUp = () => { dragging.current = false; setIsDragging(false); };

    canvas.addEventListener("mousedown", onPointerDown);
    window.addEventListener("mousemove", onPointerMove);
    window.addEventListener("mouseup", onPointerUp);
    canvas.addEventListener("touchstart", onPointerDown, { passive: true });
    window.addEventListener("touchmove", onPointerMove, { passive: true });
    window.addEventListener("touchend", onPointerUp);

    const obs = new IntersectionObserver(([entry]) => {
      if (!entry.isIntersecting) return;
      obs.disconnect();
      window.addEventListener("resize", onResize);
      onResize();
      // Defer cobe import until the globe is actually about to render — saves ~30kB on initial JS
      import("cobe").then(({ default: createGlobe }) => {
        if (cancelled || !canvas) return;
        globe = createGlobe(canvas, {
          ...KOENIG_GLOBE_CONFIG,
          width: width * 2,
          height: width * 2,
          phi: STATIC_PHI,
          theta: STATIC_THETA,
          onRender: (state) => {
            if (!dragging.current) phiRef.current += 0.003;
            state.phi = phiRef.current;
            state.theta = thetaRef.current;
            state.width = width * 2;
            state.height = width * 2;
            // Update flag overlay positions directly (no React re-render)
            GLOBE_MARKERS.forEach((m, i) => {
              const el = markerRefsRef.current[i];
              if (!el) return;
              const pos = projectMarkerDynamic(m.lat, m.lng, phiRef.current, thetaRef.current);
              if (pos) {
                el.style.display = 'flex';
                el.style.left = `${pos.x * 100}%`;
                el.style.top = `${pos.y * 100}%`;
              } else {
                el.style.display = 'none';
              }
            });
          },
        });
        setTimeout(() => { if (canvas) canvas.style.opacity = "1"; }, 100);
      });
    }, { rootMargin: "200px" });
    if (wrapRef.current) obs.observe(wrapRef.current);

    return () => {
      cancelled = true;
      obs.disconnect(); globe?.destroy(); window.removeEventListener("resize", onResize);
      canvas.removeEventListener("mousedown", onPointerDown);
      window.removeEventListener("mousemove", onPointerMove);
      window.removeEventListener("mouseup", onPointerUp);
      canvas.removeEventListener("touchstart", onPointerDown);
      window.removeEventListener("touchmove", onPointerMove);
      window.removeEventListener("touchend", onPointerUp);
    };
  }, []);

  return (
    <div ref={wrapRef} style={{ position: "relative", width: size, height: size, flexShrink: 0 }}>
      {/* outer ambient glow */}
      <div style={{
        position: "absolute", inset: -32, borderRadius: "50%",
        background: "radial-gradient(circle, rgba(6,148,209,0.12) 0%, transparent 70%)",
        pointerEvents: "none",
      }} />
      {/* Globe canvas + flag overlays clipped to circle */}
      <div style={{ position: "absolute", inset: 0, borderRadius: "50%", overflow: "hidden" }}>
        <canvas
          ref={canvasRef}
          style={{ width: "100%", height: "100%", opacity: 0, transition: "opacity 0.4s ease", display: "block", cursor: isDragging ? "grabbing" : "grab" }}
        />
        {GLOBE_MARKERS.map((m, i) => (
          <div
            key={m.label}
            ref={el => { markerRefsRef.current[i] = el; }}
            style={{
              position: "absolute", display: "none",
              /* anchor bottom-centre of flag to the projected point */
              transform: "translate(-50%, -100%) translateY(-3px)",
              pointerEvents: "none", zIndex: 5,
              flexDirection: "column", alignItems: "center", gap: 0,
            }}
          >
            <img decoding="async" loading="lazy"
              src={`https://flagcdn.com/20x15/${m.cc}.png`}
              srcSet={`https://flagcdn.com/40x30/${m.cc}.png 2x`}
              width="20" height="15"
              alt={m.label}
              style={{ borderRadius: 2, boxShadow: "0 1px 5px rgba(0,0,0,0.65)", display: "block" }}
            />
            {/* pin stem pointing at the marker dot */}
            <div style={{ width: 1.5, height: 5, background: "rgba(255,255,255,0.75)", borderRadius: 1 }} />
          </div>
        ))}
      </div>
      {/* Drag hint */}
      <div style={{
        position: "absolute", bottom: 12, left: "50%", transform: "translateX(-50%)",
        display: "flex", alignItems: "center", gap: 5,
        background: "rgba(6,148,209,0.12)", border: "1px solid rgba(6,148,209,0.22)",
        borderRadius: 20, padding: "4px 12px", pointerEvents: "none",
        opacity: isDragging ? 0 : 0.85, transition: "opacity 0.3s",
      }}>
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#0694D1" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
          <path d="M18 11V6a2 2 0 0 0-2-2v0a2 2 0 0 0-2 2v0"/><path d="M14 10V4a2 2 0 0 0-2-2v0a2 2 0 0 0-2 2v2"/><path d="M10 10.5V6a2 2 0 0 0-2-2v0a2 2 0 0 0-2 2v8"/><path d="M18 8a2 2 0 1 1 4 0v6a8 8 0 0 1-8 8h-2c-2.8 0-4.5-.86-5.99-2.34l-3.6-3.6a2 2 0 0 1 2.83-2.82L7 15"/>
        </svg>
        <span style={{ fontSize: 11, color: "#0694D1", fontWeight: 600, whiteSpace: "nowrap" }}>Drag to rotate</span>
      </div>
    </div>
  );
}

