const MS_WEBINARS = [
  { speaker:"Rahul Sharma",        initials:"RS", avatarBg:"linear-gradient(135deg,#0694D1,#50e6ff)",  vendorImg:"microsoft-cloud-t.png", title:"Create Smart Bots with Microsoft Power Virtual Agents for Enterprise Teams",  date:"Mar 7, 2026",  time:"7:00 PM IST" },
  { speaker:"Omar Abdullah",       initials:"OA", avatarBg:"linear-gradient(135deg,#093148,#0694d1)", vendorImg:"microsoft-cloud-t.png", title:"DevOps Pipelines with Azure DevOps — CI/CD Best Practices for 2026",             date:"Mar 21, 2026", time:"6:00 PM GST" },
  { speaker:"Mayur Kotoky",        initials:"MK", avatarBg:"linear-gradient(135deg,#076D9D,#4DBFEF)", vendorImg:"microsoft-cloud-t.png", title:"Microsoft Copilot Studio: Build Enterprise AI Agents Without Code",              date:"Mar 28, 2026", time:"7:00 PM IST" },
  { speaker:"Priya Nair",          initials:"PN", avatarBg:"linear-gradient(135deg,#0694D1,#093148)", vendorImg:"microsoft-cloud-t.png", title:"AZ-305 Exam Deep Dive: Azure Solutions Architect Expert Prep Session",           date:"Apr 3, 2026",  time:"7:00 PM IST" },
  { speaker:"Anjali Singh",        initials:"AS", avatarBg:"linear-gradient(135deg,#0a2c47,#0694D1)", vendorImg:"microsoft-cloud-t.png", title:"Microsoft Defender XDR & Sentinel: Mastering Modern Security Operations",       date:"Apr 9, 2026",  time:"5:00 PM GST" },
  { speaker:"David Chen",          initials:"DC", avatarBg:"linear-gradient(135deg,#0694D1,#076D9D)", vendorImg:"microsoft-cloud-t.png", title:"Power BI for Azure Data Engineers: From Raw Data to Executive Dashboards",       date:"Apr 15, 2026", time:"7:00 PM IST" },
];

function WebinarsSection({ onCTA }) {
  const [start, setStart] = React.useState(0);
  const [mobilePage, setMobilePage] = React.useState(0);
  const webDragX = React.useRef(0);
  const perPage = 3;
  const total = Math.ceil(MS_WEBINARS.length / perPage);
  const atEnd = start + perPage >= MS_WEBINARS.length;

  const VendorBadge = ({ vendorImg }) => (
    <div className="webinar-vendor-badge">
      <img decoding="async" loading="lazy" src={`/images/partners/${encodeURIComponent(vendorImg)}`} alt="" style={{ width:"100%", height:"100%", objectFit:"contain" }} />
    </div>
  );

  const CalIcon = () => (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
  );
  const ClockIcon = () => (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
  );

  return (
    <section className="webinars-sec">
      <style>{`
        .web-mobile { display:none; }
        .web-desktop { display:grid; }
        .web-desk-nav { display:flex; }
        @media(max-width:640px){
          .web-mobile   { display:block!important; }
          .web-desktop  { display:none!important; }
          .web-desk-nav { display:none!important; }
        }
        @media(max-width:600px){
          .webinars-view-all { margin-top: 15px !important; }
        }
      `}</style>

      <div style={{position:"absolute",inset:0,pointerEvents:"none"}}>
        <div style={{position:"absolute",left:"-128px",top:0,width:400,height:400,borderRadius:"50%",background:"radial-gradient(circle,rgba(6,148,209,0.18) 0%,transparent 70%)"}} />
        <div style={{position:"absolute",right:"-80px",bottom:0,width:350,height:350,borderRadius:"50%",background:"radial-gradient(circle,rgba(77,191,239,0.2) 0%,transparent 70%)"}} />
      </div>

      <div className="webinars-inner">
        <motion.div className="webinars-center-hd" initial={{opacity:0,y:20}} whileInView={{opacity:1,y:0}} viewport={{once:true,amount:0.2}} transition={{duration:0.7}}>
          <h2 className="webinars-h2">Join Our Live <em>Expert Webinars</em></h2>
          <p className="webinars-sub">Free live sessions led by certified instructors — register and attend from anywhere</p>
        </motion.div>

        {/* ── MOBILE: 1 card per page, swipe + arrow nav ── */}
        <div className="web-mobile">
          <div style={{ overflow:"hidden" }}
            onTouchStart={e => { webDragX.current = e.touches[0].clientX; }}
            onTouchEnd={e => {
              const dx = e.changedTouches[0].clientX - webDragX.current;
              if (dx < -40) setMobilePage(p => Math.min(p + 1, MS_WEBINARS.length - 1));
              else if (dx > 40) setMobilePage(p => Math.max(p - 1, 0));
            }}
          >
            <div style={{ display:"flex", width:`${MS_WEBINARS.length * 100}%`, transform:`translateX(-${mobilePage * (100/MS_WEBINARS.length)}%)`, transition:"transform 0.45s cubic-bezier(0.4,0,0.2,1)" }}>
              {MS_WEBINARS.map((w, i) => (
                <div key={i} style={{ width:`${100/MS_WEBINARS.length}%`, flexShrink:0 }}>
                  <div style={{ borderRadius:16, overflow:"hidden", background:"#fff", border:"1.5px solid #CAEFFF", boxShadow:"0 2px 12px rgba(6,148,209,0.09)" }}>
                    {/* Speaker panel */}
                    <div style={{ position:"relative", display:"flex", flexDirection:"column", alignItems:"center", paddingTop:32, paddingBottom:20, background:"#EBF8FE", backgroundImage:HEX_PATTERN, backgroundSize:"56px 100px" }}>
                      <div style={{ position:"absolute", right:12, top:12, background:"#fff", borderRadius:8, padding:6, boxShadow:"0 2px 6px rgba(0,0,0,0.08)", width:100, height:64, display:"flex", alignItems:"center", justifyContent:"center", overflow:"hidden" }}>
                        <img decoding="async" loading="lazy" src={`/images/partners/${encodeURIComponent(w.vendorImg)}`} alt="" style={{ width:"100%", height:"100%", objectFit:"contain" }} />
                      </div>
                      <div style={{ width:80, height:80, borderRadius:"50%", background:w.avatarBg, border:"4px solid #fff", boxShadow:"0 4px 16px rgba(0,0,0,0.15)", display:"flex", alignItems:"center", justifyContent:"center", fontSize:24, fontWeight:700, color:"#fff" }}>{w.initials}</div>
                      <div style={{ position:"absolute", bottom:0, left:0, right:0, height:64, background:"linear-gradient(to bottom, transparent, rgba(6,148,209,0.18))", pointerEvents:"none" }} />
                      <p style={{ position:"relative", marginTop:12, fontSize:14, fontWeight:600, color:"#093148" }}>{w.speaker}</p>
                    </div>
                    {/* Content */}
                    <div style={{ padding:"20px 20px 24px", display:"flex", flexDirection:"column", gap:16 }}>
                      <h3 style={{ textAlign:"center", fontSize:14, fontWeight:700, color:"#093148", lineHeight:1.55, display:"-webkit-box", WebkitLineClamp:3, WebkitBoxOrient:"vertical", overflow:"hidden", minHeight:"4.875rem" }}>{w.title}</h3>
                      <div style={{ display:"flex", alignItems:"center", justifyContent:"center", gap:8, fontSize:13, color:"#586274" }}>
                        <span style={{ display:"flex", alignItems:"center", gap:4 }}><CalIcon />{w.date}</span>
                        <span>|</span>
                        <span style={{ display:"flex", alignItems:"center", gap:4 }}><ClockIcon />{w.time}</span>
                      </div>
                      <button onClick={onCTA} style={{ width:"100%", borderRadius:9999, border:"2px solid #0694D1", padding:"10px 0", fontSize:14, fontWeight:600, color:"#0694D1", background:"transparent", cursor:"pointer", fontFamily:"inherit", transition:"all 0.2s" }}
                        onMouseEnter={e => { e.currentTarget.style.background="#0694D1"; e.currentTarget.style.color="#fff"; }}
                        onMouseLeave={e => { e.currentTarget.style.background="transparent"; e.currentTarget.style.color="#0694D1"; }}>Register Now</button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
          {/* Arrow nav */}
          <div style={{ display:"flex", alignItems:"center", justifyContent:"center", gap:16, marginTop:24 }}>
            <button onClick={() => setMobilePage(p => Math.max(0, p - 1))} disabled={mobilePage === 0}
              style={{ width:44, height:44, borderRadius:"50%", display:"flex", alignItems:"center", justifyContent:"center", cursor: mobilePage === 0 ? "not-allowed" : "pointer", border: mobilePage === 0 ? "1.5px solid #E5E7EB" : "1.5px solid #093148", background: mobilePage === 0 ? "#F3F4F6" : "#093148", boxShadow: mobilePage === 0 ? "none" : "0 4px 14px rgba(9,49,72,0.25)" }}>
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke={mobilePage === 0 ? "#D1D5DB" : "#fff"} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
            </button>
            <span style={{ fontSize:14, fontWeight:600, color:"#586274" }}>{mobilePage + 1} / {MS_WEBINARS.length}</span>
            <button onClick={() => setMobilePage(p => Math.min(p + 1, MS_WEBINARS.length - 1))} disabled={mobilePage === MS_WEBINARS.length - 1}
              style={{ width:44, height:44, borderRadius:"50%", display:"flex", alignItems:"center", justifyContent:"center", cursor: mobilePage === MS_WEBINARS.length - 1 ? "not-allowed" : "pointer", border: mobilePage === MS_WEBINARS.length - 1 ? "1.5px solid #E5E7EB" : "1.5px solid #093148", background: mobilePage === MS_WEBINARS.length - 1 ? "#F3F4F6" : "#093148", boxShadow: mobilePage === MS_WEBINARS.length - 1 ? "none" : "0 4px 14px rgba(9,49,72,0.25)" }}>
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke={mobilePage === MS_WEBINARS.length - 1 ? "#D1D5DB" : "#fff"} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
            </button>
          </div>
        </div>

        {/* ── DESKTOP: 3 per page, arrow nav ── */}
        <div className="webinars-grid web-desktop">
          {MS_WEBINARS.slice(start, start + perPage).map((w, i) => (
            <div key={`${start}-${i}`} className="webinar-card" style={{animation:`cardFadeUp 0.4s cubic-bezier(0.22,1,0.36,1) ${i*0.08}s both`}}>
              <div className="webinar-speaker-panel" style={{ backgroundImage: HEX_PATTERN, backgroundSize:"56px 100px" }}>
                <VendorBadge vendorImg={w.vendorImg} />
                <div className="webinar-panel-grad" />
                <div className="webinar-avatar" style={{background:w.avatarBg}}>{w.initials}</div>
                <p className="webinar-speaker-name">{w.speaker}</p>
              </div>
              <div className="webinar-card-body">
                <h3 className="webinar-title">{w.title}</h3>
                <div className="webinar-meta">
                  <span className="webinar-meta-item"><CalIcon />{w.date}</span>
                  <span className="webinar-sep">|</span>
                  <span className="webinar-meta-item"><ClockIcon />{w.time}</span>
                </div>
                <button onClick={onCTA} style={{ width:"100%", borderRadius:9999, border:"2px solid #0694D1", padding:"10px 0", fontSize:14, fontWeight:600, color:"#0694D1", background:"transparent", cursor:"pointer", fontFamily:"inherit", transition:"all 0.2s" }}
                  onMouseEnter={e => { e.currentTarget.style.background="#0694D1"; e.currentTarget.style.color="#fff"; }}
                  onMouseLeave={e => { e.currentTarget.style.background="transparent"; e.currentTarget.style.color="#0694D1"; }}>
                  Register Now
                </button>
              </div>
            </div>
          ))}
        </div>

        {/* Desktop arrow nav */}
        <div className="webinars-nav web-desk-nav">
          <button className={`webinars-nav-btn ${start === 0 ? "inactive" : "active"}`} onClick={() => setStart(s => Math.max(0, s - perPage))} disabled={start === 0} aria-label="Previous">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke={start === 0 ? "#D1D5DB" : "#fff"} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
          </button>
          <span className="webinars-nav-count">{Math.floor(start / perPage) + 1} / {total}</span>
          <button className={`webinars-nav-btn ${atEnd ? "inactive" : "active"}`} onClick={() => setStart(s => s + perPage < MS_WEBINARS.length ? s + perPage : s)} disabled={atEnd} aria-label="Next">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke={atEnd ? "#D1D5DB" : "#fff"} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
          </button>
        </div>

        <div className="webinars-view-all">
          <button className="webinars-view-all-btn" onClick={onCTA}>View All Webinars <span className="webinars-view-all-arrow">→</span></button>
        </div>
      </div>
    </section>
  );
}

